python3 - <<'PYEOF'
import json, sys

# Load existing scaffolded flow
with open('/work/output/artifacts/skill-flow-file-attachment-debug/AttachmentEchoSolution/AttachmentEcho/AttachmentEcho.flow') as f:
    flow = json.load(f)

# Load registry definitions
with open('/tmp/end_def.json') as f:
    end_raw = json.load(f)
    end_def = end_raw['Data']['Node']

with open('/tmp/script_def.json') as f:
    script_raw = json.load(f)
    script_def = script_raw['Data']['Node']

# The manual trigger definition already lives in flow['definitions'][0]
manual_def = flow['definitions'][0]

# Compose the full flow
flow['variables'] = {
    "globals": [
        {
            "id": "inputDoc",
            "direction": "in",
            "type": "file",
            "description": "Document uploaded at trigger / bound via --attachment",
            "triggerNodeId": "start"
        },
        {
            "id": "fileName",
            "direction": "out",
            "type": "string",
            "description": "The name of the uploaded file"
        }
    ],
    "nodes": [],
    "variableUpdates": {}
}

flow['nodes'] = [
    {
        "id": "start",
        "type": "core.trigger.manual",
        "typeVersion": "1.0",
        "display": {"label": "Manual trigger"},
        "inputs": {
            "entryPointId": "16fe26f7-34c3-42fb-a335-3109e8cf5606",
            "isDefaultEntryPoint": True
        }
    },
    {
        "id": "extractName",
        "type": "core.action.script",
        "typeVersion": "1.1",
        "display": {"label": "Extract file name"},
        "inputs": {
            "script": "return { fileName: $vars.start.output.inputDoc.FullName };"
        }
    },
    {
        "id": "end",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"},
        "inputs": {},
        "outputs": {
            "fileName": {
                "source": "=js:$vars.extractName.output.fileName"
            }
        }
    }
]

flow['edges'] = [
    {
        "id": "edge_start_output_extractName_input",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "extractName",
        "targetPort": "input"
    },
    {
        "id": "edge_extractName_success_end_input",
        "sourceNodeId": "extractName",
        "sourcePort": "success",
        "targetNodeId": "end",
        "targetPort": "input"
    }
]

flow['definitions'] = [manual_def, script_def, end_def]

flow['layout'] = {
    "nodes": {
        "start": {"position": {"x": 256, "y": 144}},
        "extractName": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "end": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
    }
}

out_path = '/work/output/artifacts/skill-flow-file-attachment-debug/AttachmentEchoSolution/AttachmentEcho/AttachmentEcho.flow'
with open(out_path, 'w') as f:
    json.dump(flow, f, indent=2)
print("Written OK")
print("nodes:", [n['id'] for n in flow['nodes']])
print("edges:", len(flow['edges']))
print("definitions:", [d['nodeType'] for d in flow['definitions']])
print("globals:", [v['id'] for v in flow['variables']['globals']])
PYEOF

